TEXT ·erf_asm(SB), NOSPLIT, $0-56
	MOVQ dst_base+0(FP), DI
	MOVQ src_base+24(FP), SI
	MOVQ n+48(FP), CX
	VBROADCASTSS c_explo<>(SB), Y4
