	VBROADCASTSS c_one<>(SB), Y15
loop:
	CMPQ CX, $8
	JL done
	VMOVUPS (SI), Y0
	VANDPS c_abs8<>(SB), Y0, Y1     // |x|
	VMULPS Y1, Y1, Y0              // x^2
	VXORPS c_sign8<>(SB), Y0, Y0    // -x^2
