	VFMADD213PS c_erfa2_8<>(SB), Y2, Y3
	VFMADD213PS c_erfa1_8<>(SB), Y2, Y3
	VMULPS Y2, Y3, Y3              // t*poly
	VMULPS Y3, Y0, Y0              // *e^{-x^2}
	VSUBPS Y0, Y15, Y0             // 1 - ...
	VMOVUPS (SI), Y1
	VANDPS c_sign8<>(SB), Y1, Y1    // sign(x)
	VORPS Y1, Y0, Y0
	VMOVUPS Y0, (DI)
